class Solution {
public:
    string largestNumber(vector<int>& cost, int target) {
        vector<int> dp(target + 1, -1);
        dp[0] = 0;

        for (int i = 1; i <= target; ++i) {
            for (int d = 0; d < 9; ++d) {
                if (i >= cost[d] && dp[i - cost[d]] != -1) {
                    dp[i] = max(dp[i], dp[i - cost[d]] + 1);
                }
            }
        }

        if (dp[target] == -1) return "0";

        string res;
        int rem = target;
        while (rem > 0) {
            for (int d = 8; d >= 0; --d) {
                if (rem >= cost[d] && dp[rem - cost[d]] == dp[rem] - 1) {
                    res.push_back('0' + d + 1);
                    rem -= cost[d];
                    break;
                }
            }
        }
        return res;
    }
};
